import AuthenticationServices
import CryptoKit
import Foundation
import PheronAgentCore

// MARK: - Session

struct SupabaseSession: Codable, Sendable {
    let accessToken:  String
    let refreshToken: String
    let expiresAt:    Date
    let userID:       String
    var email:        String?
    var fullName:     String?
}

// MARK: - AuthManager

@Observable
@MainActor
final class AuthManager: NSObject {

    static let shared = AuthManager()

    var isAuthenticated = false
    var session: SupabaseSession?
    var isLoading      = false
    var errorMessage:  String?

    private let keychain = KeychainHelper()
    private static let sessionKey = "supabase_session_v1"
    private var webAuthSession: ASWebAuthenticationSession?
    private var pendingCodeVerifier: String?

    private override init() {}

    // MARK: - Session Restore

    func checkSession() async {
        AgentLogger.logAudit(level: .info, agent: "Auth", message: "checkSession: starting")
        guard let session = loadSession() else {
            AgentLogger.logAudit(level: .info, agent: "Auth", message: "checkSession: no saved session found")
            return
        }

        if session.expiresAt > Date().addingTimeInterval(60) {
            AgentLogger.logAudit(level: .info, agent: "Auth",
                message: "checkSession: valid session restored — userID:\(session.userID), fullName:'\(session.fullName ?? "nil")', email:'\(session.email ?? "nil")'")
            self.session         = session
            self.isAuthenticated = true
            return
        }

        AgentLogger.logAudit(level: .info, agent: "Auth", message: "checkSession: session expired, attempting refresh")
        if let refreshed = try? await refreshToken(session.refreshToken) {
            AgentLogger.logAudit(level: .info, agent: "Auth", message: "checkSession: token refresh succeeded — userID: \(refreshed.userID)")
            self.session         = refreshed
            self.isAuthenticated = true
        } else {
            AgentLogger.logAudit(level: .error, agent: "Auth", message: "checkSession: token refresh failed, user must sign in again")
        }
    }

    // MARK: - Sign In  Apple (Supabase Web OAuth)

    func startAppleSignIn() {
        AgentLogger.logAudit(level: .info, agent: "Auth", message: "startAppleSignIn: initiating OAuth flow")

        let codeVerifier  = generateCodeVerifier()
        let codeChallenge = sha256Base64URL(codeVerifier)
        pendingCodeVerifier = codeVerifier

        var components = URLComponents(string: "\(SupabaseConfig.projectURL)/auth/v1/authorize")!
        components.queryItems = [
            URLQueryItem(name: "provider",               value: "apple"),
            URLQueryItem(name: "redirect_to",            value: "pheron://auth-callback"),
            URLQueryItem(name: "code_challenge",         value: codeChallenge),
            URLQueryItem(name: "code_challenge_method",  value: "S256"),
        ]

        guard let url = components.url else {
            AgentLogger.logAudit(level: .error, agent: "Auth", message: "startAppleSignIn: failed to build authorize URL")
            return
        }

        AgentLogger.logAudit(level: .info, agent: "Auth", message: "startAppleSignIn: opening ASWebAuthenticationSession")

        // Explicitly @Sendable so Swift does not inherit @MainActor isolation —
        // ASWebAuthenticationSession calls this from a background XPC thread.
        let completionHandler: @Sendable (URL?, (any Error)?) -> Void = { callbackURL, error in
            Task { @MainActor in
                await AuthManager.shared.handleOAuthCallback(callbackURL: callbackURL, error: error)
            }
        }

        let session = ASWebAuthenticationSession(
            url: url,
            callbackURLScheme: "pheron",
            completionHandler: completionHandler
        )
        session.presentationContextProvider = self
        session.prefersEphemeralWebBrowserSession = false
        self.webAuthSession = session
        session.start()
    }

    func handleIncomingURL(_ url: URL) {
        AgentLogger.logAudit(level: .info, agent: "Auth", message: "handleIncomingURL: \(url.absoluteString)")
        Task { @MainActor in
            await handleOAuthCallback(callbackURL: url, error: nil)
        }
    }

    private func handleOAuthCallback(callbackURL: URL?, error: Error?) async {
        webAuthSession = nil

        if let err = error as? ASWebAuthenticationSessionError, err.code == .canceledLogin {
            AgentLogger.logAudit(level: .info, agent: "Auth", message: "handleOAuthCallback: cancelled by user")
            return
        }

        if let error {
            AgentLogger.logAudit(level: .error, agent: "Auth", message: "handleOAuthCallback: session error — \(error)")
        }

        AgentLogger.logAudit(level: .info, agent: "Auth", message: "handleOAuthCallback: callbackURL=\(callbackURL?.absoluteString ?? "nil")")
        AgentLogger.logAudit(level: .info, agent: "Auth", message: "handleOAuthCallback: pendingCodeVerifier=\(pendingCodeVerifier != nil ? "SET" : "NIL")")

        guard
            let callbackURL,
            let components   = URLComponents(url: callbackURL, resolvingAgainstBaseURL: false),
            let code         = components.queryItems?.first(where: { $0.name == "code" })?.value,
            let codeVerifier = pendingCodeVerifier
        else {
            let hasCode = URLComponents(url: callbackURL ?? URL(string: "x://x")!, resolvingAgainstBaseURL: false)?
                .queryItems?.first(where: { $0.name == "code" }) != nil
            AgentLogger.logAudit(level: .error, agent: "Auth", message: "handleOAuthCallback: guard failed — hasCode:\(hasCode), hasVerifier:\(pendingCodeVerifier != nil), url:\(callbackURL?.absoluteString ?? "nil")")
            errorMessage = "Authentication failed. Please try again."
            return
        }

        AgentLogger.logAudit(level: .info, agent: "Auth", message: "handleOAuthCallback: code received, starting PKCE exchange")
        pendingCodeVerifier = nil
        isLoading = true
        defer { isLoading = false }

        do {
            let newSession = try await exchangeCodeForSession(code: code, codeVerifier: codeVerifier)
            saveSession(newSession)
            session         = newSession
            isAuthenticated = true
            errorMessage    = nil
            AgentLogger.logAudit(level: .info, agent: "Auth", message: "handleOAuthCallback: ✅ authenticated — userID:\(newSession.userID) email:\(newSession.email ?? "none")")
        } catch {
            AgentLogger.logAudit(level: .error, agent: "Auth", message: "handleOAuthCallback: ❌ PKCE exchange failed — \(error)")
            errorMessage = error.localizedDescription
        }
    }

    // MARK: - Sign Out

    func signOut() async {
        AgentLogger.logAudit(level: .info, agent: "Auth", message: "signOut: starting — userID:\(session?.userID ?? "none")")
        if let token = session?.accessToken {
            _ = try? await post(urlString: SupabaseConfig.logoutURL, body: [:], accessToken: token)
            AgentLogger.logAudit(level: .info, agent: "Auth", message: "signOut: Supabase logout request sent")
        }
        try? keychain.delete(key: Self.sessionKey)
        session         = nil
        isAuthenticated = false
        AgentLogger.logAudit(level: .info, agent: "Auth", message: "signOut: ✅ completed, session cleared")
        NotificationCenter.default.post(name: .openSignIn, object: nil)
    }

    // MARK: - Convenience

    var displayName: String {
        if let name = session?.fullName, !name.isEmpty { return name }
        if let email = session?.email, !email.isEmpty {
            if email.contains("privaterelay.appleid.com") { return "Apple Account" }
            return email
        }
        return "User"
    }
    var email:  String { session?.email  ?? "" }
    var userID: String { session?.userID ?? "" }

    // MARK: - Supabase REST Calls

    private func exchangeCodeForSession(code: String, codeVerifier: String) async throws -> SupabaseSession {
        AgentLogger.logAudit(level: .info, agent: "Auth", message: "exchangeCodeForSession: POST /auth/v1/token?grant_type=pkce")
        let body: [String: Any] = [
            "auth_code":     code,
            "code_verifier": codeVerifier
        ]
        let data = try await post(
            urlString:   "\(SupabaseConfig.tokenURL)?grant_type=pkce",
            body:        body,
            accessToken: nil
        )
        let parsed = try parseSession(from: data)
        AgentLogger.logAudit(level: .info, agent: "Auth", message: "exchangeCodeForSession: ✅ session parsed — userID:\(parsed.userID)")
        return parsed
    }

    private func refreshToken(_ refreshToken: String) async throws -> SupabaseSession {
        AgentLogger.logAudit(level: .info, agent: "Auth", message: "refreshToken: POST /auth/v1/token?grant_type=refresh_token")
        let body: [String: Any] = ["refresh_token": refreshToken]
        let data = try await post(
            urlString:   "\(SupabaseConfig.tokenURL)?grant_type=refresh_token",
            body:        body,
            accessToken: nil
        )
        let parsed = try parseSession(from: data)
        AgentLogger.logAudit(level: .info, agent: "Auth", message: "refreshToken: ✅ refreshed — userID:\(parsed.userID)")
        return parsed
    }

    private func updateUserName(_ name: String, accessToken: String) async throws {
        AgentLogger.logAudit(level: .info, agent: "Auth", message: "updateUserName: updating display name")
        let body: [String: Any] = ["data": ["full_name": name]]
        var req = URLRequest(url: URL(string: SupabaseConfig.userURL)!)
        req.httpMethod = "PUT"
        req.setValue("application/json",      forHTTPHeaderField: "Content-Type")
        req.setValue(SupabaseConfig.anonKey,  forHTTPHeaderField: "apikey")
        req.setValue("Bearer \(accessToken)", forHTTPHeaderField: "Authorization")
        req.httpBody = try JSONSerialization.data(withJSONObject: body)
        _ = try await URLSession.shared.data(for: req)
        AgentLogger.logAudit(level: .info, agent: "Auth", message: "updateUserName: ✅ name updated")
    }

    // MARK: - Helpers

    @discardableResult
    private func post(urlString: String,
                      body: [String: Any],
                      accessToken: String?) async throws -> Data {
        var request = URLRequest(url: URL(string: urlString)!, timeoutInterval: 15)
        request.httpMethod = "POST"
        request.setValue("application/json",     forHTTPHeaderField: "Content-Type")
        request.setValue(SupabaseConfig.anonKey, forHTTPHeaderField: "apikey")
        if let token = accessToken {
            request.setValue("Bearer \(token)", forHTTPHeaderField: "Authorization")
        }
        request.httpBody = try JSONSerialization.data(withJSONObject: body)
        let (data, response) = try await URLSession.shared.data(for: request)
        let statusCode = (response as? HTTPURLResponse)?.statusCode ?? 0
        AgentLogger.logAudit(level: statusCode >= 400 ? .error : .info, agent: "Auth", message: "POST \(urlString) → HTTP \(statusCode)")
        return data
    }

    private func parseSession(from data: Data) throws -> SupabaseSession {
        guard let json = try JSONSerialization.jsonObject(: data) as? [String: Any]
        else { throw AuthError.invalidResponse }

        if let msg = json["msg"]               as? String { throw AuthError.server(msg) }
        if let msg = json["message"]           as? String { throw AuthError.server(msg) }
        if let err = json["error_description"] as? String { throw AuthError.server(err) }
        if let err = json["error"]             as? String { throw AuthError.server(err) }

        guard
            let accessToken  = json["access_token"]  as? String,
            let refreshToken = json["refresh_token"]  as? String,
            let expiresIn    = json["expires_in"]     as? Double,
            let userObj      = json["user"]            as? [String: Any],
            let userID       = userObj["id"]           as? String
        else {
            AgentLogger.logAudit(level: .error, agent: "Auth", message: "parseSession: ❌ unexpected response — \(String(data: data, encoding: .utf8) ?? "unreadable")")
            throw AuthError.invalidResponse
        }

        let email = userObj["email"] as? String
        let meta  = userObj["user_metadata"] as? [String: Any]

        // Log every key so we can see what Apple/Supabase actually returns
        let metaKeys = meta?.keys.sorted().joined(separator: ", ") ?? "nil"
        AgentLogger.logAudit(level: .info, agent: "Auth",
            message: "parseSession: user_metadata keys=[\(metaKeys)]")

        // Apple OAuth via Supabase may store the name under several keys
        let fullName: String? = {
            if let fn = meta?["full_name"]   as? String, !fn.isEmpty { return fn }
            if let n  = meta?["name"]        as? String, !n.isEmpty  { return n }
            let given  = (meta?["given_name"]  as? String ?? "").trimmingCharacters(in: .whitespaces)
            let family = (meta?["family_name"] as? String ?? "").trimmingCharacters(in: .whitespaces)
            let combined = [given, family].filter { !$0.isEmpty }.joined(separator: " ")
            return combined.isEmpty ? nil : combined
        }()

        AgentLogger.logAudit(level: .info, agent: "Auth",
            message: "parseSession: resolved fullName='\(fullName ?? "nil")', email='\(email ?? "nil")'")

        return SupabaseSession(
            accessToken:  accessToken,
            refreshToken: refreshToken,
            expiresAt:    Date().addingTimeInterval(expiresIn),
            userID:       userID,
            email:        email,
            fullName:     fullName
        )
    }

    // MARK: - Keychain

    private func saveSession(_ session: SupabaseSession) {
        guard let data = try? PropertyListEncoder().encode(session) else {
            AgentLogger.logAudit(level: .error, agent: "Auth", message: "saveSession: ❌ encode failed")
            return
        }
        try? keychain.save(key: Self.sessionKey, data: data)
        AgentLogger.logAudit(level: .info, agent: "Auth", message: "saveSession: ✅ saved to keychain — userID:\(session.userID)")
    }

    private func loadSession() -> SupabaseSession? {
        guard let data = try? keychain.read(key: Self.sessionKey) else {
            AgentLogger.logAudit(level: .info, agent: "Auth", message: "loadSession: no keychain entry found")
            return nil
        }
        guard let session = try? PropertyListDecoder().decode(SupabaseSession.self, from: data) else {
            AgentLogger.logAudit(level: .error, agent: "Auth", message: "loadSession: ❌ decode failed")
            return nil
        }
        AgentLogger.logAudit(level: .info, agent: "Auth", message: "loadSession: ✅ loaded — userID:\(session.userID) expires:\(session.expiresAt)")
        return session
    }

    // MARK: - PKCE

    private func generateCodeVerifier() -> String {
        var buffer = [UInt8](repeating: 0, count: 32)
        _ = SecRandomCopyBytes(kSecRandomDefault, buffer.count, &buffer)
        return Data(buffer).base64URLEncoded()
    }

    private func sha256Base64URL(_ input: String) -> String {
        Data(SHA256.hash(data: Data(input.utf8))).base64URLEncoded()
    }
}

// MARK: - ASWebAuthenticationPresentationContextProviding

extension AuthManager: ASWebAuthenticationPresentationContextProviding {
    func presentationAnchor(for session: ASWebAuthenticationSession) -> ASPresentationAnchor {
        NSApp.windows.first(where: { $0.isKeyWindow })
            ?? NSApp.windows.first(where: { $0.isVisible && $0.styleMask.contains(.titled) })
            ?? NSWindow()
    }
}

// MARK: - Data + Base64URL

private extension Data {
    func base64URLEncoded() -> String {
        base64EncodedString()
            .replacingOccurrences(of: "+", : "-")
            .replacingOccurrences(of: "/", : "_")
            .trimmingCharacters(in: CharacterSet(charactersIn: "="))
    }
}

// MARK: - Errors

enum AuthError: LocalizedError {
    case invalidResponse
    case server(String)

    var errorDescription: String? {
        switch self {
        case .invalidResponse:  return "Unexpected response from authentication server."
        case .server(let msg):  return msg
        }
    }
}
